-- Issued invoice source facts are protected at the database layer, including direct and bulk writers.
-- Unchanged values and non-financial notes remain editable. Release requires a future explicit invoice adjustment workflow.
CREATE TRIGGER invoice_lessons_update BEFORE UPDATE OF group_id,student,subject,teacher_name,planned_start,planned_end,actual_start,actual_end,status,chargeable,reviewed_at,reviewed_by,attendance_kind,session_id,replacement_for ON lessons WHEN (OLD.group_id IS NOT NEW.group_id OR OLD.student IS NOT NEW.student OR OLD.subject IS NOT NEW.subject OR OLD.teacher_name IS NOT NEW.teacher_name OR OLD.planned_start IS NOT NEW.planned_start OR OLD.planned_end IS NOT NEW.planned_end OR OLD.actual_start IS NOT NEW.actual_start OR OLD.actual_end IS NOT NEW.actual_end OR OLD.status IS NOT NEW.status OR OLD.chargeable IS NOT NEW.chargeable OR OLD.reviewed_at IS NOT NEW.reviewed_at OR OLD.reviewed_by IS NOT NEW.reviewed_by OR OLD.attendance_kind IS NOT NEW.attendance_kind OR OLD.session_id IS NOT NEW.session_id OR OLD.replacement_for IS NOT NEW.replacement_for) AND ((EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='lesson' AND il.source_id=OLD.id) OR EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=OLD.group_id AND ib.student_name=OLD.student AND il.month=strftime('%Y-%m',coalesce((SELECT actual_start FROM class_sessions ils WHERE ils.id=OLD.session_id AND ils.group_id=OLD.group_id),OLD.actual_start,OLD.planned_start),'+8 hours'))) OR (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='lesson' AND il.source_id=NEW.id) OR EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=NEW.group_id AND ib.student_name=NEW.student AND il.month=strftime('%Y-%m',coalesce((SELECT actual_start FROM class_sessions ils WHERE ils.id=NEW.session_id AND ils.group_id=NEW.group_id),NEW.actual_start,NEW.planned_start),'+8 hours')))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_lessons_delete BEFORE DELETE ON lessons WHEN (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='lesson' AND il.source_id=OLD.id) OR EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=OLD.group_id AND ib.student_name=OLD.student AND il.month=strftime('%Y-%m',coalesce((SELECT actual_start FROM class_sessions ils WHERE ils.id=OLD.session_id AND ils.group_id=OLD.group_id),OLD.actual_start,OLD.planned_start),'+8 hours'))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_lessons_insert BEFORE INSERT ON lessons WHEN (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='lesson' AND il.source_id=NEW.id) OR EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=NEW.group_id AND ib.student_name=NEW.student AND il.month=strftime('%Y-%m',coalesce((SELECT actual_start FROM class_sessions ils WHERE ils.id=NEW.session_id AND ils.group_id=NEW.group_id),NEW.actual_start,NEW.planned_start),'+8 hours'))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_class_sessions_update BEFORE UPDATE OF group_id,teacher_name,subject,session_type,planned_start,planned_end,actual_start,actual_end,teaching_status,attendance_reviewed_at,attendance_reviewed_by,status,classroom_id ON class_sessions WHEN (OLD.group_id IS NOT NEW.group_id OR OLD.teacher_name IS NOT NEW.teacher_name OR OLD.subject IS NOT NEW.subject OR OLD.session_type IS NOT NEW.session_type OR OLD.planned_start IS NOT NEW.planned_start OR OLD.planned_end IS NOT NEW.planned_end OR OLD.actual_start IS NOT NEW.actual_start OR OLD.actual_end IS NOT NEW.actual_end OR OLD.teaching_status IS NOT NEW.teaching_status OR OLD.attendance_reviewed_at IS NOT NEW.attendance_reviewed_at OR OLD.attendance_reviewed_by IS NOT NEW.attendance_reviewed_by OR OLD.status IS NOT NEW.status OR OLD.classroom_id IS NOT NEW.classroom_id) AND ((EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='session' AND il.source_id=OLD.id) OR EXISTS(SELECT 1 FROM class_session_participants ilp WHERE ilp.group_id=OLD.group_id AND ilp.session_id=OLD.id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=OLD.group_id AND ib.student_name=ilp.student_name AND il.month=strftime('%Y-%m',coalesce(OLD.actual_start,OLD.planned_start),'+8 hours')))) OR (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='session' AND il.source_id=NEW.id) OR EXISTS(SELECT 1 FROM class_session_participants ilp WHERE ilp.group_id=NEW.group_id AND ilp.session_id=NEW.id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=NEW.group_id AND ib.student_name=ilp.student_name AND il.month=strftime('%Y-%m',coalesce(NEW.actual_start,NEW.planned_start),'+8 hours'))))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_class_sessions_delete BEFORE DELETE ON class_sessions WHEN (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='session' AND il.source_id=OLD.id) OR EXISTS(SELECT 1 FROM class_session_participants ilp WHERE ilp.group_id=OLD.group_id AND ilp.session_id=OLD.id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=OLD.group_id AND ib.student_name=ilp.student_name AND il.month=strftime('%Y-%m',coalesce(OLD.actual_start,OLD.planned_start),'+8 hours')))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_class_session_participants_update BEFORE UPDATE OF group_id,session_id,lesson_id,student_name,attendance_status,arrived_at,left_at ON class_session_participants WHEN (OLD.group_id IS NOT NEW.group_id OR OLD.session_id IS NOT NEW.session_id OR OLD.lesson_id IS NOT NEW.lesson_id OR OLD.student_name IS NOT NEW.student_name OR OLD.attendance_status IS NOT NEW.attendance_status OR OLD.arrived_at IS NOT NEW.arrived_at OR OLD.left_at IS NOT NEW.left_at) AND ((EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='lesson' AND il.source_id=OLD.lesson_id) OR EXISTS(SELECT 1 FROM class_sessions cs WHERE cs.id=OLD.session_id AND cs.group_id=OLD.group_id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=OLD.group_id AND ib.student_name=OLD.student_name AND il.month=strftime('%Y-%m',coalesce(cs.actual_start,cs.planned_start),'+8 hours')))) OR (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='lesson' AND il.source_id=NEW.lesson_id) OR EXISTS(SELECT 1 FROM class_sessions cs WHERE cs.id=NEW.session_id AND cs.group_id=NEW.group_id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=NEW.group_id AND ib.student_name=NEW.student_name AND il.month=strftime('%Y-%m',coalesce(cs.actual_start,cs.planned_start),'+8 hours'))))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_class_session_participants_delete BEFORE DELETE ON class_session_participants WHEN (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='lesson' AND il.source_id=OLD.lesson_id) OR EXISTS(SELECT 1 FROM class_sessions cs WHERE cs.id=OLD.session_id AND cs.group_id=OLD.group_id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=OLD.group_id AND ib.student_name=OLD.student_name AND il.month=strftime('%Y-%m',coalesce(cs.actual_start,cs.planned_start),'+8 hours')))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_class_session_participants_insert BEFORE INSERT ON class_session_participants WHEN (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='lesson' AND il.source_id=NEW.lesson_id) OR EXISTS(SELECT 1 FROM class_sessions cs WHERE cs.id=NEW.session_id AND cs.group_id=NEW.group_id AND EXISTS(SELECT 1 FROM invoice_source_locks il JOIN billing_students ib ON ib.id=il.student_id AND ib.group_id=il.group_id WHERE il.source_type='student_month' AND il.group_id=NEW.group_id AND ib.student_name=NEW.student_name AND il.month=strftime('%Y-%m',coalesce(cs.actual_start,cs.planned_start),'+8 hours')))) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_billing_adjustments_insert BEFORE INSERT ON billing_adjustments WHEN EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='student_month' AND il.student_id=NEW.student_id AND il.month=NEW.month) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_billing_adjustments_update BEFORE UPDATE OF group_id,student_id,month,line_id,amount_cents,basis_hash,reason ON billing_adjustments WHEN (OLD.group_id IS NOT NEW.group_id OR OLD.student_id IS NOT NEW.student_id OR OLD.month IS NOT NEW.month OR OLD.line_id IS NOT NEW.line_id OR OLD.amount_cents IS NOT NEW.amount_cents OR OLD.basis_hash IS NOT NEW.basis_hash OR OLD.reason IS NOT NEW.reason) AND (EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='student_month' AND il.student_id=OLD.student_id AND il.month=OLD.month) OR EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='student_month' AND il.student_id=NEW.student_id AND il.month=NEW.month)) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_billing_adjustments_delete BEFORE DELETE ON billing_adjustments WHEN EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=OLD.group_id AND il.source_type='student_month' AND il.student_id=OLD.student_id AND il.month=OLD.month) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_billing_rate_versions_insert BEFORE INSERT ON billing_rate_versions WHEN EXISTS(SELECT 1 FROM billing_rates br JOIN invoice_source_locks il ON il.group_id=br.group_id AND il.student_id=br.student_id WHERE br.id=NEW.rate_id AND br.group_id=NEW.group_id AND il.source_type='student_month' AND NEW.effective_from<date(il.month||'-01','+1 month')) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;

CREATE TRIGGER invoice_billing_policy_versions_insert BEFORE INSERT ON billing_policy_versions WHEN EXISTS(SELECT 1 FROM invoice_source_locks il WHERE il.group_id=NEW.group_id AND il.source_type='student_month' AND NEW.effective_from<date(il.month||'-01','+1 month')) BEGIN SELECT RAISE(ABORT,'invoice_source_locked'); END;
